import React from 'react';
import axios from 'axios';

class InventoryList extends React.Component {
    url = 'http://localhost:5000';
    state = [{
                id: "",
                warehouseID: "",
                warehouseName: "",
                itemName: "",
                description: "",
                category: "",
                status: "",
                quantity: -1
            }]


    componentDidMount() {
        axios.get(`${this.url}/inventory`)
            .then(response => {
                this.setState(response.data);
            })
            .catch(error => console.error(error));
    }

    editHandler = () => {
        axios.put(`${this.url}/inventory`, {

                })
            .then(response => {
                this.setState(response.data);
            })
            .catch(error => console.error(error));
    }
    deleteHandler = () => {
        axios.delete(`${this.url}/inventory/:id`)
            .then(response => {
                this.setState(response.data);
            })
            .catch(error => console.error(error));
    }

    render() {
        return (
            <div>
                <h1>Inventory</h1>
                <table>
                    <thead>
                        <th></th>
                    </thead>
                    <tbody>
                        {this.state.map(item => 
                        <tr>
                                <td>item.warehouseName</td>
                                <td>item.category</td>
                                <td>item.status</td>
                                <td>item.quantity</td>
                                <td>item.warhouseName</td>
                                <td>
                                    <button onClick={ this.editHandler }><img src="./public/incons/delete-outline-24px.svg" alt="Edit icon" /></button>
                                    <button onClick={ this.deleteHandler }><img src="" alt="Delete icon"/></button>
                                </td>
                        </tr>
                        )}
                    </tbody>
                    </table>
            </div>
        );
    }


}

export default   InventoryList;
